#!/usr/bin/env python3
"""Explicit original -> 26.3 resource conversion; Python standard library only.

Run from any directory. Default writes build/generated/remainingResources;
--check validates sources, mappings, references and fixtures without writing.
--check-output additionally compares every generated byte and rejects stale files.

Adapters: item_model (also emits the modern item definition), block_model,
blockstate, particle, crafting_recipe, tag, reviewed_json, structure_copy.
Version-sensitive loot/advancement/dimension/worldgen JSON uses reviewed_json:
pin source_sha256, supply review, and explicit JSON-pointer replacements/removals.
This deliberately cannot certify arbitrary 1.16 data as current-schema data.
Structures similarly require explicit review: copying NBT is not DataFixer conversion.
Existing texture/sound/language copying stays owned by processResources.
"""
import argparse
import copy
import hashlib
import json
import re
import struct
import zlib
import zipfile
from functools import lru_cache
from pathlib import Path, PurePosixPath

ROOT = Path(__file__).resolve().parents[2]
MANIFEST = ROOT / "fabric/migration/remaining-resource-schema.json"
OUTPUT = ROOT / "fabric/build/generated/remainingResources"
FIXTURES = ROOT / "fabric/migration/fixtures/remaining-resource-cases.json"
RESOURCE_ROOTS = [ROOT / "fabric/src/main/resources", ROOT / "src/main/resources"]
KINDS = {"item_model", "block_model", "blockstate", "particle", "crafting_recipe", "tag", "reviewed_json", "structure_copy", "forge_bucket"}


def bucket_mask(entry):
    """Decode the pinned original Forge RGBA drip mask, no image dependency/download."""
    path = ROOT / relative_path(entry["mask"])
    require(path.resolve().is_relative_to((ROOT / "fabric/src/main/resources/assets").resolve()), "Bucket mask outside owned resources")
    raw = path.read_bytes()
    require(hashlib.sha256(raw).hexdigest() == entry["mask_sha256"], "Forge bucket mask source digest mismatch")
    require(raw[:8] == b"\x89PNG\r\n\x1a\n" and struct.unpack(">IIBBBBB", raw[16:29]) == (16, 16, 8, 6, 0, 0, 0), "Unmapped bucket mask PNG format")
    compressed, cursor = bytearray(), 8
    while cursor < len(raw):
        size = struct.unpack(">I", raw[cursor:cursor+4])[0]
        if raw[cursor+4:cursor+8] == b"IDAT": compressed.extend(raw[cursor+8:cursor+8+size])
        cursor += size + 12
    decoded = zlib.decompress(compressed)
    require(len(decoded) == 16 * 65, "Invalid mask scanline count")
    previous, mask = [0] * 64, []
    for y in range(16):
        mode, row = decoded[y*65], list(decoded[y*65+1:(y+1)*65])
        require(mode <= 4, "Invalid PNG row filter")
        for i in range(64):
            a, b, c = row[i-4] if i >= 4 else 0, previous[i], previous[i-4] if i >= 4 else 0
            if mode == 1: prediction = a
            elif mode == 2: prediction = b
            elif mode == 3: prediction = (a+b)//2
            elif mode == 4:
                p = a+b-c
                prediction = min([(abs(p-a),0,a),(abs(p-b),1,b),(abs(p-c),2,c)])[2]
            else: prediction = 0
            row[i] = (row[i] + prediction) & 255
        mask.append([row[x*4+3] for x in range(16)])
        previous = row
    require(all(a in {0,255} for row in mask for a in row), "Partial-alpha bucket mask needs explicit adapter")
    return mask


def require(condition, message):
    if not condition:
        raise ValueError(message)


def json_load(path):
    def unique(pairs):
        result = {}
        for key, value in pairs:
            require(key not in result, f"Duplicate JSON key {key!r} in {path}")
            result[key] = value
        return result
    return json.loads(Path(path).read_text(encoding="utf-8"), object_pairs_hook=unique,
                      parse_constant=lambda x: (_ for _ in ()).throw(ValueError(f"Non-finite JSON number: {x}")))


def encoded(value):
    return (json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + "\n").encode()


def relative_path(value):
    require(isinstance(value, str) and value and "\\" not in value, f"Invalid path: {value!r}")
    p = PurePosixPath(value)
    require(not p.is_absolute() and ".." not in p.parts and str(p) == value, f"Unsafe path: {value}")
    return p


def source_path(value):
    p = ROOT / relative_path(value)
    require(p.resolve().is_relative_to((ROOT / "src/main").resolve()), f"Source outside original source tree: {value}")
    require(p.is_file(), f"Missing original source: {value}")
    return p


def identifier(value):
    require(isinstance(value, str) and re.fullmatch(r"[a-z0-9_.-]+:[a-z0-9_./-]+", value)
            and ".." not in value, f"Invalid resource identifier: {value!r}")
    return value.split(":", 1)


def ingredient(value):
    # 26.3 crafting Ingredient.CODEC uses strings / tag strings or alternatives.
    if isinstance(value, list):
        require(value, "Empty ingredient alternatives")
        return [ingredient(v) for v in value]
    require(isinstance(value, dict) and len(value) == 1, f"Unsupported legacy ingredient: {value}")
    if "item" in value:
        identifier(value["item"])
        return value["item"]
    require("tag" in value, f"Unsupported ingredient: {value}")
    identifier(value["tag"])
    return "#" + value["tag"]


def recipe(data):
    data = copy.deepcopy(data)
    kind = data.get("type")
    require(kind in {"minecraft:crafting_shaped", "minecraft:crafting_shapeless"}, f"Unmapped recipe type: {kind}")
    require(set(data) <= {"type", "group", "pattern", "key", "ingredients", "result", "category", "show_notification"}, "Unmapped recipe fields")
    if kind.endswith("shaped"):
        require(data.get("pattern") and data.get("key"), "Shaped recipe missing pattern/key")
        data["key"] = {k: ingredient(v) for k, v in data["key"].items()}
    else:
        require(data.get("ingredients"), "Shapeless recipe missing ingredients")
        data["ingredients"] = [ingredient(v) for v in data["ingredients"]]
    result = data.get("result")
    require(isinstance(result, dict) and set(result) <= {"item", "count"} and "item" in result, "Unmapped recipe result")
    identifier(result["item"])
    data["result"] = {"id": result["item"], **({"count": result["count"]} if "count" in result else {})}
    require(isinstance(result.get("count", 1), int) and result.get("count", 1) > 0, "Invalid recipe count")
    return data


def patch_reviewed(data, entry):
    data = copy.deepcopy(data)
    for patch in entry.get("patches", []):
        require(set(patch) <= {"path", "value", "remove", "reason"} and patch.get("reason"), "Patch needs explicit reason")
        path = patch.get("path", "")
        require(path.startswith("/") and len(path) > 1, "Patch needs non-root JSON pointer")
        keys = [k.replace("~1", "/").replace("~0", "~") for k in path[1:].split("/")]
        node = data
        for key in keys[:-1]:
            node = node[int(key)] if isinstance(node, list) else node[key]
        key = int(keys[-1]) if isinstance(node, list) else keys[-1]
        if patch.get("remove"):
            require("value" not in patch, "Patch cannot remove and replace")
            del node[key]
        else:
            require("value" in patch, "Replacement patch missing value")
            node[key] = patch["value"]
    return data


def convert_entry(entry):
    require(set(entry) <= {"id", "kind", "source", "target", "item_definition", "source_sha256", "review", "patches", "references", "mask", "mask_sha256", "fluid_texture"}, "Unmapped manifest fields")
    ns, name = identifier(entry.get("id"))
    kind = entry.get("kind")
    require(kind in KINDS, f"Unmapped resource kind: {kind}")
    source = source_path(entry.get("source"))
    target = str(relative_path(entry.get("target")))
    require(target.startswith((f"assets/{ns}/", f"data/{ns}/")), f"Target namespace does not match {entry['id']}")
    if kind in {"reviewed_json", "structure_copy"}:
        require(entry.get("review") and entry.get("source_sha256") == hashlib.sha256(source.read_bytes()).hexdigest(),
                f"Version-sensitive resource needs current source digest and schema review: {source}")
    if kind == "structure_copy":
        require(target == f"data/{ns}/structure/{name}.nbt" and source.suffix == ".nbt", "Structure requires singular target directory")
        return {target: source.read_bytes()}
    require(target.endswith(".json"), "JSON adapter target must end in .json")
    data = json_load(source)
    require(isinstance(data, dict), "Resource JSON must be an object")
    result = {}
    if kind == "forge_bucket":
        require(data == {"parent": "forge:item/bucket_drip", "loader": "forge:bucket", "fluid": "jojo:boiling_blood"}, "Unmapped Forge bucket model")
        require(target == f"assets/{ns}/models/item/{name}.json" and entry.get("item_definition") == f"assets/{ns}/items/{name}.json", "Bucket output/ID mismatch")
        identifier(entry["fluid_texture"])
        elements = []
        for y, row in enumerate(bucket_mask(entry)):
            for x, alpha in enumerate(row):
                if not alpha: continue
                # Original DynamicBucketModel depths. Two flat faces, no invented side walls.
                elements.append({"from": [x,15-y,7.498], "to": [x+1,16-y,8.502], "light_emission": 15,
                                 "faces": {"north": {"uv": [x+1,y,x,y+1], "texture": "#fluid"},
                                           "south": {"uv": [x,y,x+1,y+1], "texture": "#fluid"}}})
        game = Path.home() / ".gradle/caches/fabric-loom/26.3/minecraft-client.jar"
        with zipfile.ZipFile(game) as archive:
            display = json.loads(archive.read("assets/minecraft/models/item/generated.json"))["display"]
        result[f"assets/{ns}/models/item/{name}_fluid.json"] = encoded({"gui_light": "front", "display": display, "textures": {"fluid": entry["fluid_texture"], "particle": entry["fluid_texture"]}, "elements": elements})
        result[entry["item_definition"]] = encoded({"model": {"type": "minecraft:composite", "models": [
            {"type": "minecraft:model", "model": f"{ns}:item/{name}"}, {"type": "minecraft:model", "model": f"{ns}:item/{name}_fluid"}]}})
        data = {"parent": "minecraft:item/bucket"}
    elif kind in {"item_model", "block_model"}:
        category = "item" if kind == "item_model" else "block"
        require(target == f"assets/{ns}/models/{category}/{name}.json", "Model target does not match ID")
        require("overrides" not in data, "Legacy model overrides require a dedicated modern item dispatch mapping")
        require(set(data) <= {"parent", "textures", "elements", "display", "ambientocclusion", "gui_light", "credit"}, "Unmapped model fields")
        require("parent" in data or data.get("elements") or (kind == "block_model" and set(data) == {"textures"} and set(data["textures"]) == {"particle"}), "Model has no parent or geometry")
        if kind == "item_model":
            item = entry.get("item_definition")
            require(item == f"assets/{ns}/items/{name}.json", "Item definition missing or mismatched")
            result[item] = encoded({"model": {"type": "minecraft:model", "model": f"{ns}:item/{name}"}})
    elif kind == "blockstate":
        require(target == f"assets/{ns}/blockstates/{name}.json", "Invalid blockstate path")
        require(set(data) in ({"variants"}, {"multipart"}), "Unmapped blockstate fields")
    elif kind == "particle":
        require(target == f"assets/{ns}/particles/{name}.json", "Invalid particle path")
        require(set(data) == {"textures"} and isinstance(data["textures"], list) and data["textures"], "Unmapped particle schema")
    elif kind == "crafting_recipe":
        require(target == f"data/{ns}/recipe/{name}.json", "Recipe requires singular target directory")
        data = recipe(data)
    elif kind == "tag":
        require(re.fullmatch(rf"data/{re.escape(ns)}/tags/(item|block|entity_type|fluid|game_event)/{re.escape(name)}\.json", target), "Unmapped tag registry/path")
        require(set(data) <= {"replace", "values"} and isinstance(data.get("values"), list), "Unmapped tag fields")
        for value in data["values"]:
            value = value.get("id") if isinstance(value, dict) else value
            identifier(value.removeprefix("#"))
    elif kind == "reviewed_json":
        require(target.startswith(f"data/{ns}/") and not re.search(r"/(recipes|loot_tables|advancements|structures)/", target), "Legacy data directory in reviewed target")
        data = patch_reviewed(data, entry)
    result[target] = encoded(data)
    return result


def resource_exists(path, outputs, original=False):
    roots = RESOURCE_ROOTS if original else RESOURCE_ROOTS[:1]
    return path in outputs or any((root / path).is_file() for root in roots)


@lru_cache(maxsize=1)
def vanilla_resources():
    """Use the pinned local game as schema/reference authority, never download it."""
    game = Path.home() / ".gradle/caches/fabric-loom/26.3/minecraft-client.jar"
    if game.is_file():
        with zipfile.ZipFile(game) as archive:
            return set(archive.namelist())
    return None


def validate_references(outputs, entries):
    def ref(value, category):
        ns, name = identifier(value if ":" in value else "minecraft:" + value)
        path = f"assets/{ns}/{category}/{name}." + ("png" if category == "textures" else "json")
        if ns == "minecraft":
            known = vanilla_resources()
            # built-in/generated is deliberately resolved by the model baker, not a file.
            builtin = category == "models" and name in {"builtin/generated", "builtin/entity"}
            require(builtin or (known is not None and path in known),
                    f"Missing vanilla reference (requires local pinned 26.3 client jar): {value}")
            return
        require(resource_exists(path, outputs, original=category == "textures"), f"Missing {category} reference: {value}")

    for path, raw in outputs.items():
        if not path.endswith(".json"):
            continue
        data = json.loads(raw)
        if "/models/" in path:
            if "parent" in data:
                ref(data["parent"], "models")
            textures = data.get("textures", {})
            def texture(value, seen=()):
                if value.startswith("#"):
                    key = value[1:]
                    require(key not in seen, f"Cyclic texture alias: {path} {key}")
                    # Parent-defined aliases are valid; only local aliases can be resolved here.
                    if key in textures:
                        texture(textures[key], (*seen, key))
                    else:
                        require("parent" in data, f"Unknown texture alias: {path} {key}")
                else:
                    ref(value, "textures")
            for value in textures.values():
                texture(value)
            for element in data.get("elements", []):
                for face in element.get("faces", {}).values():
                    texture(face["texture"])
        elif "/particles/" in path:
            for value in data["textures"]:
                ns, name = identifier(value if ":" in value else "minecraft:" + value)
                ref(f"{ns}:particle/{name}", "textures")
        elif "/blockstates/" in path or "/items/" in path:
            def walk(node):
                if isinstance(node, dict):
                    for k, v in node.items():
                        if k == "model" and isinstance(v, str):
                            ref(v, "models")
                        else:
                            walk(v)
                elif isinstance(node, list):
                    for value in node:
                        walk(value)
            walk(data)
    for entry in entries:
        for path in entry.get("references", []):
            relative_path(path)
            require(resource_exists(path, outputs), f"Missing explicit output reference: {path}")


def render_outputs(manifest=None):
    manifest = json_load(MANIFEST) if manifest is None else manifest
    require(manifest.get("version") == 1 and manifest.get("target") == "26.3", "Unmapped manifest version or target")
    entries = manifest.get("resources")
    require(isinstance(entries, list) and entries, "Missing resource manifest entries")
    outputs, ids = {}, set()
    for entry in entries:
        key = (entry.get("kind"), entry.get("id"))
        require(key not in ids, f"Duplicate resource manifest entry: {key}")
        ids.add(key)
        for path, data in convert_entry(entry).items():
            require(path not in outputs, f"Duplicate generated resource key: {path}")
            require(not (RESOURCE_ROOTS[0] / path).exists(), f"Generated resource collides with handwritten resource: {path}")
            outputs[path] = data
    validate_references(outputs, entries)
    return dict(sorted(outputs.items()))


def materialize(outputs, directory, check=False):
    directory = Path(directory)
    # Dedicated generated roots only. No source tree may be an output directory.
    require(directory.resolve().is_relative_to((ROOT / "fabric/build/generated").resolve()), "Output must be under fabric/build/generated")
    existing = {str(p.relative_to(directory)) for p in directory.rglob("*") if p.is_file()}
    require(not any(p.is_symlink() for p in directory.rglob("*")), "Generated output tree must not contain symlinks")
    if check:
        require(existing == set(outputs), f"Generated file set differs: missing={set(outputs)-existing}, stale={existing-set(outputs)}")
        for path, raw in outputs.items():
            require((directory / path).read_bytes() == raw, f"Stale generated output: {path}")
        return
    for path, raw in outputs.items():
        destination = directory / relative_path(path)
        destination.parent.mkdir(parents=True, exist_ok=True)
        if not destination.exists() or destination.read_bytes() != raw:
            destination.write_bytes(raw)
    for path in existing - set(outputs):
        (directory / path).unlink()


def check_fixtures():
    fixtures = json_load(FIXTURES)
    outputs = render_outputs()
    for path, expected in fixtures["outputs"].items():
        require(json.loads(outputs[path]) == expected, f"Resource fixture mismatch: {path}")
    for case in fixtures["reject"]:
        manifest = copy.deepcopy(json_load(MANIFEST))
        if case == "duplicate_entry":
            manifest["resources"].append(copy.deepcopy(manifest["resources"][0]))
        elif case == "missing_source":
            manifest["resources"][0]["source"] = "src/main/resources/missing.json"
        elif case == "unsafe_target":
            manifest["resources"][0]["target"] = "../escape.json"
        elif case == "missing_item_definition":
            del manifest["resources"][0]["item_definition"]
        elif case == "legacy_overrides":
            manifest["resources"][0].update(id="jojo:tommy_gun", source="src/main/resources/assets/jojo/models/item/tommy_gun.json", target="assets/jojo/models/item/tommy_gun.json", item_definition="assets/jojo/items/tommy_gun.json")
        else:
            raise ValueError(f"Unknown fixture {case}")
        try:
            render_outputs(manifest)
        except ValueError:
            continue
        raise ValueError(f"Invalid resource fixture was accepted: {case}")
    for case in fixtures.get("recipes", []):
        require(recipe(case["source"]) == case["target"], "Recipe schema fixture mismatch")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--check-output", action="store_true")
    parser.add_argument("--manifest", type=Path, default=MANIFEST)
    parser.add_argument("--output", type=Path, default=OUTPUT)
    args = parser.parse_args()
    try:
        outputs = render_outputs(json_load(args.manifest))
        if args.manifest.resolve() == MANIFEST.resolve():
            check_fixtures()
        if args.check_output or not args.check:
            materialize(outputs, args.output, check=args.check_output)
        print(f"Remaining resources: {len(outputs)} validated outputs" + (" (source checks only)" if args.check and not args.check_output else ""))
    except (ValueError, KeyError, TypeError, OSError) as error:
        parser.exit(1, f"Resource conversion failed: {error}\n")


if __name__ == "__main__":
    main()
